1	import { AppManager } from "./manager/AppManager.js";
2	import { FrameScheduler } from "./utils/FrameScheduler.js";
3	
4	async function start(): Promise<void> {
5	  await AppManager.init();
6	}
7	
8	function deferStart(): void {
9	  if (document.readyState === "loading") {
10	    document.addEventListener("DOMContentLoaded", () => deferStart(), {
11	      once: true,
12	    });
13	    return;
14	  }
15	  if (typeof requestIdleCallback !== "undefined") {
16	    requestIdleCallback(
17	      () => {
18	        FrameScheduler.request(() => void start());
19	      },
20	      { timeout: 2000 },
21	    );
22	  } else {
23	    FrameScheduler.request(() => void start());
24	  }
25	}
26	
27	function registerLifecycle(): void {
28	  // beforeunload는 bfcache 진입을 차단한다. pagehide + persisted 체크로 대체.
29	  window.addEventListener("pagehide", (e) => {
30	    if (!e.persisted) {
31	      AppManager.disposeBootstrap();
32	    }
33	  });
34	  // bfcache에서 복원될 때 전체 앱 재초기화
35	  window.addEventListener("pageshow", (e) => {
36	    if (e.persisted) {
37	      void AppManager.init();
38	    }
39	  });
40	}
41	
42	registerLifecycle();
43	deferStart();
