351	    const keywordCount = Math.max(ABOUT_HERO_SLOGAN.keywordCount, 1);
352	    const clampedProgress = Helpers.clamp01(progress);
353	    const windowedProgress = this._resolveAboutHeroSloganKeywordProgress(
354	      clampedProgress,
