1152	  private async _runContactIntroSequence(engine: Engine): Promise<void> {
1153	    if (
1154	      this._contactFlowStage === "ready" ||
1155	      this._contactFlowStage === "outtro" ||
1156	      this._contactFlowStage === "success"
1157	    ) {
1158	      return;
1159	    }
1160	    if (this._contactIntroTask) {
1161	      await this._contactIntroTask;
1162	      return;
1163	    }
1164	
1165	    this._contactIntroTask = this._enqueueContactFlow(async () => {
1166	      if (this._contactFlowStage !== "idle") return;
1167	      this._contactFlowStage = "intro";
1168	      this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_PENDING);
1169	      try {
1170	        await this._playContactTheatreStep(
1171	          engine,
1172	          () => this._pageTheatreBinder.startIntroIfNeeded(engine),
1173	        );
1174	      } catch (error) {
1175	        this._contactFlowStage = "idle";
1176	        this._syncContactDomState(null);
1177	        throw error;
1178	      }
1179	      this._contactFlowStage = "ready";
1180	      this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_READY);
1181	    }).finally(() => {
1182	      this._contactIntroTask = null;
1183	    });
1184	
1185	    await this._contactIntroTask;
1186	  }
